#include <bits/stdc++.h>
using namespace std;

string in;
size_t pos_ = 0;

static void pushUnit(string& key, unsigned unit) { key += char(unit >> 8); key += char(unit & 255); }

// Decodes a JSON string starting at the opening quote into a key of UTF-16 code units,
// so escaped and raw spellings of the same text compare equal.
string readString() {
    string key;
    pos_++;  // opening quote
    while (in[pos_] != '"') {
        unsigned char c = in[pos_];
        if (c == '\\') {
            char e = in[pos_ + 1];
            pos_ += 2;
            switch (e) {
                case 'b': pushUnit(key, 8); break;
                case 'f': pushUnit(key, 12); break;
                case 'n': pushUnit(key, 10); break;
                case 'r': pushUnit(key, 13); break;
                case 't': pushUnit(key, 9); break;
                case 'u': pushUnit(key, stoul(in.substr(pos_, 4), nullptr, 16)); pos_ += 4; break;
                default: pushUnit(key, (unsigned char)e);
            }
            continue;
        }
        // Raw UTF-8: decode one code point, then emit UTF-16 units.
        unsigned cp; int len;
        if (c < 0x80) cp = c, len = 1;
        else if (c < 0xE0) cp = c & 0x1F, len = 2;
        else if (c < 0xF0) cp = c & 0x0F, len = 3;
        else cp = c & 0x07, len = 4;
        for (int i = 1; i < len; i++) cp = (cp << 6) | (in[pos_ + i] & 0x3F);
        pos_ += len;
        if (cp >= 0x10000) { cp -= 0x10000; pushUnit(key, 0xD800 + (cp >> 10)); pushUnit(key, 0xDC00 + (cp & 0x3FF)); }
        else pushUnit(key, cp);
    }
    pos_++;  // closing quote
    return key;
}

vector<int> parent_, size_;
int find(int x) {
    while (parent_[x] != x) { parent_[x] = parent_[parent_[x]]; x = parent_[x]; }
    return x;
}

int main() {
    char chunk[1 << 16];
    for (size_t got; (got = fread(chunk, 1, sizeof chunk, stdin)) > 0;) in.append(chunk, got);
    // Shape: [[product,...],[[a,b],...]]. Depth 2 in the first sub-array holds products,
    // depth 3 holds pair endpoints.
    unordered_map<string, int> position;
    vector<int> endpoints;
    int depth = 0, arraysAtDepth2 = 0;
    while (pos_ < in.size()) {
        char c = in[pos_];
        if (c == '[') { depth++; if (depth == 2) arraysAtDepth2++; pos_++; }
        else if (c == ']') { depth--; pos_++; }
        else if (c == '"') {
            string key = readString();
            if (depth == 2 && arraysAtDepth2 == 1) {
                int id = position.size();
                position.emplace(key, id);
            } else {
                endpoints.push_back(position.at(key));
            }
        } else pos_++;
    }
    int n = position.size();
    parent_.resize(n); size_.assign(n, 1);
    iota(parent_.begin(), parent_.end(), 0);
    for (size_t i = 0; i + 1 < endpoints.size(); i += 2) {
        int x = find(endpoints[i]), y = find(endpoints[i + 1]);
        if (x == y) continue;
        if (size_[x] < size_[y]) swap(x, y);
        parent_[y] = x;
        size_[x] += size_[y];
    }
    vector<int> answer;
    for (int i = 0; i < n; i++) if (parent_[i] == i) answer.push_back(size_[i]);
    sort(answer.begin(), answer.end());
    if (answer.empty()) { puts("0"); return 0; }
    string out;
    for (size_t i = 0; i < answer.size(); i++) { if (i) out += ' '; out += to_string(answer[i]); }
    puts(out.c_str());
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static String in;
    static int pos = 0;
    static int[] parent, size;

    // Decodes a JSON string starting at the opening quote (Java strings are UTF-16, like the key we need).
    static String readString() {
        StringBuilder sb = new StringBuilder();
        pos++;
        while (in.charAt(pos) != '"') {
            char c = in.charAt(pos);
            if (c == '\\') {
                char e = in.charAt(pos + 1);
                pos += 2;
                switch (e) {
                    case 'b' -> sb.append('\b');
                    case 'f' -> sb.append('\f');
                    case 'n' -> sb.append('\n');
                    case 'r' -> sb.append('\r');
                    case 't' -> sb.append('\t');
                    case 'u' -> { sb.append((char) Integer.parseInt(in.substring(pos, pos + 4), 16)); pos += 4; }
                    default -> sb.append(e);
                }
            } else {
                sb.append(c);
                pos++;
            }
        }
        pos++;
        return sb.toString();
    }

    static int find(int x) {
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }

    public static void main(String[] args) throws IOException {
        in = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        // Shape: [[product,...],[[a,b],...]]. Depth 2 in the first sub-array holds products,
        // depth 3 holds pair endpoints.
        HashMap<String, Integer> position = new HashMap<>();
        int[] endpoints = new int[16];
        int endpointCount = 0, depth = 0, arraysAtDepth2 = 0;
        while (pos < in.length()) {
            char c = in.charAt(pos);
            if (c == '[') { depth++; if (depth == 2) arraysAtDepth2++; pos++; }
            else if (c == ']') { depth--; pos++; }
            else if (c == '"') {
                String key = readString();
                if (depth == 2 && arraysAtDepth2 == 1) position.put(key, position.size());
                else {
                    if (endpointCount == endpoints.length) endpoints = Arrays.copyOf(endpoints, endpointCount * 2);
                    endpoints[endpointCount++] = position.get(key);
                }
            } else pos++;
        }
        int n = position.size();
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
        for (int i = 0; i + 1 < endpointCount; i += 2) {
            int x = find(endpoints[i]), y = find(endpoints[i + 1]);
            if (x == y) continue;
            if (size[x] < size[y]) { int t = x; x = y; y = t; }
            parent[y] = x;
            size[x] += size[y];
        }
        int roots = 0;
        int[] answer = new int[n];
        for (int i = 0; i < n; i++) if (parent[i] == i) answer[roots++] = size[i];
        if (roots == 0) { System.out.println(0); return; }
        Arrays.sort(answer, 0, roots);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < roots; i++) { if (i > 0) out.append(' '); out.append(answer[i]); }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"sort"
	"strconv"
	"unicode/utf8"
)

var in []byte
var pos int

func pushUnit(key []byte, unit int) []byte { return append(key, byte(unit>>8), byte(unit)) }

// readString decodes a JSON string starting at the opening quote into a key of UTF-16 code
// units, so escaped and raw spellings of the same text compare equal (lone surrogates included).
func readString() string {
	key := []byte{}
	pos++
	for in[pos] != '"' {
		c := in[pos]
		if c == '\\' {
			e := in[pos+1]
			pos += 2
			switch e {
			case 'b':
				key = pushUnit(key, 8)
			case 'f':
				key = pushUnit(key, 12)
			case 'n':
				key = pushUnit(key, 10)
			case 'r':
				key = pushUnit(key, 13)
			case 't':
				key = pushUnit(key, 9)
			case 'u':
				v, _ := strconv.ParseUint(string(in[pos:pos+4]), 16, 32)
				key = pushUnit(key, int(v))
				pos += 4
			default:
				key = pushUnit(key, int(e))
			}
			continue
		}
		r, size := utf8.DecodeRune(in[pos:])
		pos += size
		if r >= 0x10000 {
			r -= 0x10000
			key = pushUnit(key, 0xD800+int(r>>10))
			key = pushUnit(key, 0xDC00+int(r&0x3FF))
		} else {
			key = pushUnit(key, int(r))
		}
	}
	pos++
	return string(key)
}

var parent, size []int

func find(x int) int {
	for parent[x] != x {
		parent[x] = parent[parent[x]]
		x = parent[x]
	}
	return x
}

func main() {
	in, _ = io.ReadAll(os.Stdin)
	// Shape: [[product,...],[[a,b],...]]. Depth 2 in the first sub-array holds products,
	// depth 3 holds pair endpoints.
	position := map[string]int{}
	endpoints := []int{}
	depth, arraysAtDepth2 := 0, 0
	for pos < len(in) {
		switch in[pos] {
		case '[':
			depth++
			if depth == 2 {
				arraysAtDepth2++
			}
			pos++
		case ']':
			depth--
			pos++
		case '"':
			key := readString()
			if depth == 2 && arraysAtDepth2 == 1 {
				position[key] = len(position)
			} else {
				endpoints = append(endpoints, position[key])
			}
		default:
			pos++
		}
	}
	n := len(position)
	parent = make([]int, n)
	size = make([]int, n)
	for i := range parent {
		parent[i], size[i] = i, 1
	}
	for i := 0; i+1 < len(endpoints); i += 2 {
		x, y := find(endpoints[i]), find(endpoints[i+1])
		if x == y {
			continue
		}
		if size[x] < size[y] {
			x, y = y, x
		}
		parent[y] = x
		size[x] += size[y]
	}
	answer := []int{}
	for i := 0; i < n; i++ {
		if parent[i] == i {
			answer = append(answer, size[i])
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	if len(answer) == 0 {
		w.WriteString("0\n")
		return
	}
	sort.Ints(answer)
	for i, v := range answer {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(v))
	}
	w.WriteByte('\n')
}
